/*
 * A367084  Indices k such that A367083(k) and A367083(k+1) are both odd.
 * https://oeis.org/A367084
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is generated by the rule a(0) = 0 for n >= 1, a(n) = a(n-1)
 *            + d_n with d_1 = 7, and thereafter d_{k+1} = 9 for 4 or 5
 *            consecutive steps alternating between 4 and 5, then d = 7 again.
 *            The pattern of 9's is: 4,5,4,5,... (starting with 4 after the
 *            initial 7) which reproduces the first differenc...
 * Range:     u8 n <= 29, u16 n <= 58, u32 n <= 58, u64 n <= 58, u128 n <= 58,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>

seq_t a(idx_t n) {
    if (n == 0) return (seq_t)0;
    seq_t prev = (seq_t)0;
    bool diff_is_seven = true;   /* next difference is 7 */
    int run_len = 4;             /* length of upcoming run of 9's */
    int counter = 0;             /* how many 9's have been added in current run */

    for (idx_t i = 1; i <= n; ++i) {
        if (diff_is_seven) {
            prev += (seq_t)7;
            diff_is_seven = false;   /* next will be the first 9 of the run */
            counter = 0;             /* reset counter for 9's in the new run */
        } else {
            prev += (seq_t)9;
            ++counter;
            if (counter == run_len) {
                diff_is_seven = true;          /* next difference will be 7 */
                run_len = (run_len == 4 ? 5 : 4); /* alternate run length */
            }
        }
    }
    return prev;
}
